from typing import List, Dict, Protocol

class Renderer(Protocol):
    def render(self, data: List[Dict]) -> str:
        ...


class CSVRenderer:
    def render(self, data: List[Dict]) -> str:
        header = ','.join(data[0].keys())
        lines = [header]
        for row in data:
            lines.append(','.join(str(v) for v in row.values()))
        return '\n'.join(lines)


class JSONRenderer:
    def render(self, data: List[Dict]) -> str:
        import json
        return json.dumps(data, indent=2)


class HTMLRenderer:
    def render(self, data: List[Dict]) -> str:
        rows_html = ''.join(
            f"<tr>{''.join(f'<td>{v}</td>' for v in row.values())}</tr>"
            for row in data
        )
        headers = ''.join(f'<th>{k}</th>' for k in data[0].keys())
        return f"<table><thead><tr>{headers}</tr></thead><tbody>{rows_html}</tbody></table>"


FORMAT_REGISTRY = {
    'csv': CSVRenderer,
    'json': JSONRenderer,
    'html': HTMLRenderer,
}


class ReportGenerator:
    def generate(self, data: List[Dict], format: str) -> str:
        renderer_cls = FORMAT_REGISTRY.get(format)
        if not renderer_cls:
            raise ValueError(f"Unknown format: {format}")
        renderer = renderer_cls()
        return renderer.render(data)
